/**
 * GameScience semantic token contract.
 * Themes must implement every custom property listed here.
 * Values here are structural fallbacks only; visual identity lives in theme CSS.
 */

:root {
  /* Colour */
  --background: 1 0 0;
  --foreground: 0.206 0.039 265.5;

  --surface: 1 0 0;
  --surface-subtle: 0.984 0.003 247.9;
  --surface-raised: 1 0 0;
  --surface-overlay: 1 0 0;

  --border: 0.926 0.013 255;
  --border-strong: 0.71 0.035 256.8;
  --focus-ring: 0.545 0.215 262.7;

  --primary: 0.545 0.215 262.7;
  --primary-hover: 0.499 0.217 262.7;
  --primary-active: 0.453 0.194 262.7;
  --primary-foreground: 1 0 0;

  --secondary: 0.968 0.007 247.9;
  --secondary-hover: 0.926 0.013 255;
  --secondary-active: 0.869 0.02 253.4;
  --secondary-foreground: 0.206 0.039 265.5;

  --accent: 0.678 0.148 238.1;
  --accent-foreground: 1 0 0;

  --muted: 0.968 0.007 247.9;
  --muted-foreground: 0.556 0.04 256.8;

  --success: 0.599 0.158 149.7;
  --success-foreground: 1 0 0;
  --warning: 0.77 0.165 70.6;
  --warning-foreground: 0.284 0.063 53.9;
  --danger: 0.579 0.214 27.2;
  --danger-foreground: 1 0 0;
  --information: 0.678 0.148 238.1;
  --information-foreground: 1 0 0;

  /* Shape */
  --radius-control: 0.5rem;
  --radius-card: 0.75rem;
  --radius-panel: 1rem;
  --radius-overlay: 1rem;
  --radius-pill: 9999px;

  --border-width-control: 1px;
  --border-width-panel: 1px;

  /* Typography */
  --font-display: "Source Sans 3", "Segoe UI", sans-serif;
  --font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --font-weight-heading: 700;
  --font-weight-label: 600;
  --font-weight-body: 400;

  --tracking-heading: -0.02em;
  --tracking-label: 0.02em;
  --text-transform-label: none;

  /* Sizing and density */
  --control-height-sm: 2rem;
  --control-height-md: 2.5rem;
  --control-height-lg: 3rem;

  --control-padding-inline-sm: 0.75rem;
  --control-padding-inline-md: 1rem;
  --control-padding-inline-lg: 1.25rem;

  --panel-padding-sm: 0.75rem;
  --panel-padding-md: 1.25rem;
  --panel-padding-lg: 1.75rem;

  --section-gap: 1.5rem;
  --content-max-width: 42rem;

  /* Depth */
  --shadow-control: 0 1px 2px rgb(15 23 42 / 0.06);
  --shadow-card: 0 4px 16px rgb(15 23 42 / 0.08);
  --shadow-overlay: 0 16px 40px rgb(15 23 42 / 0.16);
  --shadow-focus: 0 0 0 3px oklch(var(--focus-ring) / 0.35);

  /* Motion */
  --duration-fast: 120ms;
  --duration-standard: 200ms;
  --duration-emphasis: 320ms;

  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-emphasis: cubic-bezier(0.16, 1, 0.3, 1);

  --press-scale: 0.98;
  --hover-translate: -1px;

  /* Context-tunable type scale */
  --type-scale-display: clamp(1.75rem, 2vw + 1rem, 2.5rem);
  --type-scale-title: clamp(1.25rem, 1vw + 1rem, 1.75rem);
  --type-scale-body: 1rem;
  --type-scale-label: 0.875rem;
  --type-scale-code: 1.125rem;
  --type-scale-micro: 0.75rem;

  /* Numeric/data face — maps to mono; not a sans label font */
  --font-data: var(--font-mono);
}

html {
  font-family: var(--font-body);
  font-weight: var(--font-weight-body);
  line-height: 1.5;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
.gs-display,
.gs-display-hero,
.gs-title-page,
.gs-title-section {
  font-family: var(--font-display);
  font-weight: var(--font-weight-heading);
  letter-spacing: var(--tracking-heading);
  line-height: 1.15;
}

h1,
.gs-display,
.gs-display-hero {
  font-size: var(--type-scale-display);
}

h2,
.gs-title,
.gs-title-page {
  font-size: var(--type-scale-title);
}

h3,
.gs-title-section {
  font-family: var(--font-display);
  font-weight: var(--font-weight-heading);
  font-size: var(--type-scale-title);
  letter-spacing: var(--tracking-heading);
  line-height: 1.2;
}

p,
.gs-body {
  font-size: var(--type-scale-body);
}

label,
.gs-label {
  font-size: var(--type-scale-label);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: var(--text-transform-label);
}

code,
kbd,
.gs-mono {
  font-family: var(--font-mono);
  font-size: var(--type-scale-code);
}

.gs-data {
  font-family: var(--font-data, var(--font-mono));
  font-size: var(--type-scale-code);
  font-variant-numeric: tabular-nums;
}

.gs-micro {
  font-size: var(--type-scale-micro);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: var(--text-transform-label);
}

/** Dotted eyebrow: · LABEL · — decoration via CSS, not hard-coded in multiple components */
.gs-eyebrow-dotted {
  display: inline-flex;
  align-items: center;
  gap: 0.4em;
}

.gs-eyebrow-dotted::before,
.gs-eyebrow-dotted::after {
  content: "·";
  opacity: 0.7;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-fast: 0ms;
    --duration-standard: 0ms;
    --duration-emphasis: 0ms;
    --press-scale: 1;
    --hover-translate: 0px;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

.gs-pressable:active:not(:disabled) {
  transform: scale(var(--press-scale));
}

/**
 * Experience-context density and scale.
 * Applied via [data-context] on GameScienceProvider.
 */

[data-context="participant"] {
  --control-height-sm: 2.5rem;
  --control-height-md: 2.75rem;
  --control-height-lg: 3.25rem;
  --control-padding-inline-sm: 1rem;
  --control-padding-inline-md: 1.25rem;
  --control-padding-inline-lg: 1.5rem;
  --panel-padding-sm: 1rem;
  --panel-padding-md: 1.5rem;
  --panel-padding-lg: 2rem;
  --section-gap: 1.25rem;
  --content-max-width: 28rem;
  --type-scale-display: clamp(1.75rem, 4vw + 1rem, 2.25rem);
  --type-scale-title: clamp(1.25rem, 2vw + 1rem, 1.5rem);
  --type-scale-body: 1.0625rem;
  --type-scale-label: 0.9375rem;
  --type-scale-code: 1.25rem;
  --type-scale-micro: 0.75rem;
}

[data-context="facilitator"] {
  --control-height-sm: 2rem;
  --control-height-md: 2.25rem;
  --control-height-lg: 2.75rem;
  --control-padding-inline-sm: 0.75rem;
  --control-padding-inline-md: 0.875rem;
  --control-padding-inline-lg: 1.125rem;
  --panel-padding-sm: 0.75rem;
  --panel-padding-md: 1rem;
  --panel-padding-lg: 1.25rem;
  --section-gap: 1rem;
  --content-max-width: 72rem;
  --type-scale-display: clamp(1.5rem, 1vw + 1rem, 2rem);
  --type-scale-title: 1.25rem;
  --type-scale-body: 0.9375rem;
  --type-scale-label: 0.8125rem;
  --type-scale-code: 1rem;
  --type-scale-micro: 0.6875rem;
}

[data-context="shared-display"] {
  --control-height-sm: 3rem;
  --control-height-md: 3.5rem;
  --control-height-lg: 4rem;
  --panel-padding-sm: 1.5rem;
  --panel-padding-md: 2.5rem;
  --panel-padding-lg: 3.5rem;
  --section-gap: 2.5rem;
  --content-max-width: 90rem;
  --type-scale-display: clamp(3rem, 5vw + 1rem, 5.5rem);
  --type-scale-title: clamp(2rem, 3vw + 1rem, 3.5rem);
  --type-scale-body: clamp(1.25rem, 1.2vw + 1rem, 1.75rem);
  --type-scale-label: clamp(1rem, 0.8vw + 0.75rem, 1.25rem);
  --type-scale-code: clamp(2.5rem, 4vw + 1rem, 4.5rem);
  --type-scale-micro: clamp(0.875rem, 0.5vw + 0.65rem, 1rem);
  --radius-panel: 1.25rem;
}

[data-context="participant"] .gs-touch-target {
  min-height: 44px;
  min-width: 44px;
}

[data-context="shared-display"] .gs-interactive-only {
  display: none !important;
}

@import "./tokens.css";
@import "./typography.css";
@import "./motion.css";
@import "./responsive.css";

/**
 * Framework-neutral GameScience foundations entry.
 *
 * Safe to import in Tailwind 3 and Tailwind 4 consumers.
 * Does not include @tailwind directives, @apply, or remote @import.
 * Fonts are application-owned — see docs/font-loading.md.
 */

html {
  background-color: oklch(var(--background));
  min-height: 100%;
}

*,
*::before,
*::after {
  border-color: oklch(var(--border));
}

body {
  min-height: 100vh;
  margin: 0;
  background-color: oklch(var(--background));
  color: oklch(var(--foreground));
  font-family: var(--font-body);
  font-weight: var(--font-weight-body);
  -webkit-font-smoothing: antialiased;
}

.gs-panel {
  border-width: var(--border-width-panel);
}

:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}

export {
  REQUIRED_THEME_TOKENS,
  SUPPORTED_CONTEXTS,
  SUPPORTED_REGISTERS,
  SUPPORTED_THEMES,
  type ExperienceContext,
  type GameTheme,
  type ThemeRegister,
  type ThemeToken,
} from "./theme-contract";

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Shared accessibility helpers for GameScience components. */

export function announcePoliteness(
  state: "idle" | "busy" | "assertive",
): "off" | "polite" | "assertive" {
  if (state === "assertive") return "assertive";
  if (state === "busy") return "polite";
  return "off";
}

export function statusLabel(status: string, fallbackMap: Record<string, string>): string {
  return fallbackMap[status] ?? status.replace(/-/g, " ");
}

import type { ConnectionState } from "@/types/game";

export type CompactConnectionState = "connected" | "reconnecting" | "offline";

/** Map banner-capable connection states onto compact ConnectionStatus props. */
export function toCompactConnectionState(state: ConnectionState): CompactConnectionState {
  switch (state) {
    case "connected":
    case "restored":
      return "connected";
    case "connecting":
    case "reconnecting":
    case "degraded":
      return "reconnecting";
    default:
      return "offline";
  }
}

import { createContext, useContext } from "react";
import type { GameTheme } from "@/themes/theme-contract";

export interface GameThemeContextValue {
  theme: GameTheme;
}

export const GameThemeContext = createContext<GameThemeContextValue | null>(null);

export function useGameTheme(): GameThemeContextValue {
  const value = useContext(GameThemeContext);
  if (!value) {
    throw new Error("useGameTheme must be used within GameScienceProvider");
  }
  return value;
}

import { createContext, useContext } from "react";
import type { ExperienceContext } from "@/themes/theme-contract";

export interface ExperienceContextValue {
  context: ExperienceContext;
}

export const ExperienceReactContext = createContext<ExperienceContextValue | null>(null);

export function useExperienceContext(): ExperienceContextValue {
  const value = useContext(ExperienceReactContext);
  if (!value) {
    throw new Error("useExperienceContext must be used within GameScienceProvider");
  }
  return value;
}

import { useEffect, useLayoutEffect, type ReactNode } from "react";
import { cn } from "@/lib/cn";
import {
  SUPPORTED_CONTEXTS,
  SUPPORTED_REGISTERS,
  SUPPORTED_THEMES,
  THEME_DEFAULT_REGISTERS,
  type ExperienceContext,
  type GameTheme,
  type ThemeRegister,
} from "@/themes/theme-contract";
import { ExperienceReactContext } from "./experience-context";
import { GameThemeContext } from "./game-theme-context";

export interface GameScienceProviderProps {
  theme: GameTheme;
  context: ExperienceContext;
  /**
   * Optional visual register within a theme, for themes that ship more than
   * one intensity. A theme with no declared register ignores the attribute.
   * See THEME_DEFAULT_REGISTERS in the theme contract.
   */
  register?: ThemeRegister;
  children: ReactNode;
  className?: string;
  /**
   * When true (default), syncs data-theme / data-context / data-register onto
   * document.documentElement so Radix portals, Sonner toasts, and body/html
   * backgrounds inherit theme tokens.
   * Disable only in specialised test hosts that manage document attributes themselves.
   */
  syncDocumentAttributes?: boolean;
}

function assertTheme(theme: string): asserts theme is GameTheme {
  if (!(SUPPORTED_THEMES as readonly string[]).includes(theme)) {
    throw new Error(
      `Unsupported GameScience theme "${theme}". Supported themes: ${SUPPORTED_THEMES.join(", ")}`,
    );
  }
}

function assertContext(context: string): asserts context is ExperienceContext {
  if (!(SUPPORTED_CONTEXTS as readonly string[]).includes(context)) {
    throw new Error(
      `Unsupported experience context "${context}". Supported contexts: ${SUPPORTED_CONTEXTS.join(", ")}`,
    );
  }
}

function assertRegister(register: string): asserts register is ThemeRegister {
  if (!(SUPPORTED_REGISTERS as readonly string[]).includes(register)) {
    throw new Error(
      `Unsupported GameScience register "${register}". Supported registers: ${SUPPORTED_REGISTERS.join(", ")}`,
    );
  }
}

const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

function resolveRegister(
  theme: GameTheme,
  register: ThemeRegister | undefined,
): ThemeRegister | undefined {
  if (register) return register;
  return THEME_DEFAULT_REGISTERS[theme];
}

function syncDocumentTheme(
  theme: GameTheme,
  context: ExperienceContext,
  register: ThemeRegister | undefined,
) {
  if (typeof document === "undefined") {
    return () => undefined;
  }

  const root = document.documentElement;
  const previous = {
    theme: root.getAttribute("data-theme"),
    context: root.getAttribute("data-context"),
    register: root.getAttribute("data-register"),
    gamescience: root.getAttribute("data-gamescience-ui"),
  };

  root.setAttribute("data-theme", theme);
  root.setAttribute("data-context", context);
  root.setAttribute("data-gamescience-ui", "");
  if (register) {
    root.setAttribute("data-register", register);
  } else {
    root.removeAttribute("data-register");
  }

  return () => {
    if (previous.theme == null) {
      root.removeAttribute("data-theme");
    } else {
      root.setAttribute("data-theme", previous.theme);
    }

    if (previous.context == null) {
      root.removeAttribute("data-context");
    } else {
      root.setAttribute("data-context", previous.context);
    }

    if (previous.register == null) {
      root.removeAttribute("data-register");
    } else {
      root.setAttribute("data-register", previous.register);
    }

    if (previous.gamescience == null) {
      root.removeAttribute("data-gamescience-ui");
    } else {
      root.setAttribute("data-gamescience-ui", previous.gamescience);
    }
  };
}

export function GameScienceProvider({
  theme,
  context,
  register: registerProp,
  children,
  className,
  syncDocumentAttributes = true,
}: GameScienceProviderProps) {
  assertTheme(theme);
  assertContext(context);
  if (registerProp) assertRegister(registerProp);
  const register = resolveRegister(theme, registerProp);

  useIsomorphicLayoutEffect(() => {
    if (!syncDocumentAttributes) {
      return undefined;
    }
    return syncDocumentTheme(theme, context, register);
  }, [theme, context, register, syncDocumentAttributes]);

  return (
    <GameThemeContext.Provider value={{ theme }}>
      <ExperienceReactContext.Provider value={{ context }}>
        <div
          data-theme={theme}
          data-context={context}
          data-register={register}
          data-gamescience-ui
          className={cn("min-h-screen bg-background font-body text-foreground", className)}
        >
          {children}
        </div>
      </ExperienceReactContext.Provider>
    </GameThemeContext.Provider>
  );
}

GameScienceProvider.displayName = "GameScienceProvider";

export { GameScienceProvider, type GameScienceProviderProps } from "./gamescience-provider";
export { useGameTheme, type GameThemeContextValue } from "./game-theme-context";
export { useExperienceContext, type ExperienceContextValue } from "./experience-context";

export type GameStage =
  | "join"
  | "lobby"
  | "role-allocation"
  | "briefing"
  | "information"
  | "discussion"
  | "decision"
  | "vote"
  | "event"
  | "results"
  | "debrief";

export type StageStatus = "not-started" | "ready" | "active" | "paused" | "complete" | "locked";

/**
 * Connection presentation states.
 * Compact `ConnectionStatus` uses `connected` | `reconnecting` | `offline`.
 * `ConnectionBanner` may use the broader set.
 */
export type ConnectionState =
  | "connected"
  | "connecting"
  | "reconnecting"
  | "degraded"
  | "disconnected"
  | "offline"
  | "paused"
  | "restored";

export type ReadinessState = "not-ready" | "ready" | "submitted" | "waiting";

export interface ParticipantSummary {
  id: string;
  displayName: string;
  connection: ConnectionState;
  readiness: ReadinessState;
}

export interface SessionSummary {
  code: string;
  title?: string;
  participantCount: number;
  expectedParticipantCount?: number;
  stage: GameStage;
  status: StageStatus;
}

import { Toaster as Sonner, type ToasterProps } from "sonner";

/**
 * Sonner is the only approved transient notification system.
 * Do not add legacy toast/toaster/use-toast implementations.
 */
function Toaster(props: ToasterProps) {
  return (
    <Sonner
      theme="system"
      className="gs-toaster toaster group"
      toastOptions={{
        classNames: {
          toast:
            "group toast group-[.toaster]:bg-surface group-[.toaster]:text-foreground group-[.toaster]:border-border group-[.toaster]:shadow-overlay",
          description: "group-[.toast]:text-muted-foreground",
          actionButton: "group-[.toast]:bg-primary group-[.toast]:text-primary-foreground",
          cancelButton: "group-[.toast]:bg-muted group-[.toast]:text-muted-foreground",
        },
      }}
      {...props}
    />
  );
}

Toaster.displayName = "Toaster";

export { Toaster };
export { toast } from "sonner";
